using Windows.Win32;
using Windows.Win32.UI.Input.KeyboardAndMouse;

namespace Taswib;

/// <summary>Small Win32 helpers shared by several files. P/Invoke declarations are generated by CsWin32 from NativeMethods.txt.</summary>
static class Win
{
    /// <summary>Installed keyboard layouts (HKL values; low word = language id).</summary>
    public static unsafe nint[] Layouts()
    {
        var n = PInvoke.GetKeyboardLayoutList(0, null);
        var list = new HKL[n];
        fixed (HKL* p = list) PInvoke.GetKeyboardLayoutList(n, p);
        return list.Select(h => (nint)h.Value).ToArray();
    }
}
